//! Session artifact inventory shared by clients and the host.

use serde::{Deserialize, Serialize};

use crate::PluginId;

/// An identifier scoped to a session's artifact inventory.
#[derive(Clone, Debug, Eq, Hash, PartialEq, Serialize, Deserialize)]
#[serde(transparent)]
pub struct ArtifactId(String);

impl ArtifactId {
    /// Wraps an identifier generated by the host.
    #[must_use]
    pub fn new(id: String) -> Self {
        Self(id)
    }

    /// The identifier used by the download endpoint.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// What produced the file.
#[derive(Clone, Debug, Eq, Hash, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum ArtifactOrigin {
    /// A client attached the file.
    UserUpload,
    /// An assistant response produced the file.
    AssistantOutput {
        /// The turn, when available.
        turn: Option<u64>,
        /// The index within the output message.
        part_index: Option<u32>,
    },
    /// A plugin published the file.
    Plugin {
        /// The plugin that produced it.
        plugin_id: PluginId,
        /// The tool call that produced it.
        call_id: String,
    },
    /// A host tool produced the file.
    Tool {
        /// The tool call that produced it.
        call_id: String,
    },
    /// A stored message contains the file.
    Message,
}

/// Metadata for a session artifact. Its bytes are requested separately.
#[derive(Clone, Debug, Eq, Hash, PartialEq, Serialize, Deserialize)]
pub struct SessionArtifact {
    /// The session-scoped reference.
    pub id: ArtifactId,
    /// The content digest.
    pub blob_id: String,
    /// Its content type.
    pub mime_type: String,
    /// Its display name, when supplied.
    pub name: Option<String>,
    /// How many bytes are stored.
    pub bytes: u64,
    /// When the producer attached the file, in Unix milliseconds.
    pub created_at: Option<i64>,
    /// The producer known to the host.
    pub origin: ArtifactOrigin,
}

/// Optional metadata supplied when uploading a file to a session.
#[derive(Debug, Default, Deserialize, Serialize)]
pub struct UploadOptions {
    /// The original file name, when available.
    pub name: Option<String>,
}
